import {altitudeLevels,sliceAt,signalRGB,freeSpaceRSSI,chartSample,gridCSV,report} from './analysis.js';
const $=id=>document.getElementById(id),emit=(name,detail)=>document.dispatchEvent(new CustomEvent(name,{detail}));
const workspace=document.querySelector('.workspace'),analysis=document.createElement('section'),comparison=document.createElement('section');analysis.id='analysispage';comparison.id='comparisonpage';analysis.className=comparison.className='reportpage hidden';
analysis.innerHTML=`<div class="eyebrow">SURVEY INTELLIGENCE / ANALYSIS</div><h2>Beyond the signal average.</h2><p class="lede">Inspect measured RF performance, locate connected weak regions, and compare reception against an ideal free-space baseline.</p><div class="reportbar"><span class="mono" id="analysisname">Load a survey to begin</span><div class="actions"><button id="gridexport">Export voxel CSV</button><button id="jsonexport">Export summary JSON</button><button id="pngexport">Export 3D PNG</button></div></div><div id="analysiswarning" class="analysisnotice hidden"></div><div class="reportcards" id="analysiscards"></div><div class="analysiscontrols"><label>Dead-zone threshold <input id="analysisdead" type="number" value="-105" step="1"> dBm</label><label>Baseline TX power <input id="txpower" type="number" value="17" step=".5"> dBm</label><label>Frequency <input id="frequency" type="number" value="433" min="1" step=".1"> MHz</label><span class="hint" id="txassumption">17 dBm is an assumed baseline; edit to match your beacon.</span></div><div class="chartgrid"><article class="chartcard"><h3>RSSI vs time · received packets</h3><div class="chartframe"><canvas id="timechart" aria-label="RSSI versus elapsed time chart" role="img"></canvas></div></article><article class="chartcard"><h3>RSSI vs altitude</h3><div class="chartframe"><canvas id="altchart" aria-label="RSSI versus altitude chart" role="img"></canvas></div></article><article class="chartcard"><h3>RSSI vs distance from beacon</h3><div class="chartframe"><canvas id="distancechart" aria-label="RSSI versus beacon distance with free-space baseline chart" role="img"></canvas></div><p class="hint">Ideal Friis baseline uses the configured TX power and frequency, isotropic antennas, and zero additional losses. It is not a fitted prediction. Distances below 1 m are excluded from the baseline. Charts show at most about 2,000 points with deep fades retained.</p></article></div><article class="clustercard"><h3>Connected dead zones</h3><p class="hint">Six-neighbor connected components of interpolated cells below the selected dead-zone threshold. Click a region to focus the 3D camera. No-signal timeout markers are analyzed separately.</p><table class="clustertable"><thead><tr><th>Region</th><th>Centroid X / Y / Z · m</th><th>Cells</th><th>Estimated volume</th><th>Min RSSI</th><th>Inspect</th></tr></thead><tbody id="clusterrows"></tbody></table><div id="clustersummary" class="hint"></div></article><p id="exportstatus" class="exportstatus" role="status"></p>`;
comparison.innerHTML=`<div class="eyebrow">ALTITUDE COMPARISON / OBSERVATION COVERAGE</div><h2>What ground-level testing misses.</h2><p class="lede">Compare an interpolated flight slice with observations collected near the requested ground height. Empty cells are unknown, not strong signal.</p><div class="analysiscontrols"><label>Flight slice <select id="compalt" aria-label="Flight slice altitude"></select></label><label>Ground height <input id="groundheight" type="number" value="1.5" step=".1"> m</label><span class="hint">Use the same altitude reference as your CSV.</span></div><div class="slicegrid"><article class="slicecard"><h3>Flight altitude · interpolated RF field</h3><canvas id="flightslice" aria-label="Interpolated top-down flight altitude heatmap" role="img"></canvas><div class="slicestatus" id="flightcoverage"></div></article><article class="slicecard"><h3>2D Ground-Level Testing (Incomplete Data)</h3><canvas id="groundslice" aria-label="Measured ground-level coverage heatmap, missing cells hatched" role="img"></canvas><div class="slicestatus" id="groundcoverage"></div></article></div><div class="slicescale"><span class="hint">RSSI · weaker → stronger</span><div class="gradient"></div></div><p class="analysisnotice" id="comparisondetail">Load a survey to compare altitude slices.</p>`;
workspace.after(analysis,comparison);
const inspector=document.createElement('aside');inspector.className='map-inspector hidden';inspector.innerHTML=`<button class="close-inspector" aria-label="Close survey details">×</button><div class="eyebrow">SURVEY DETAILS</div><div id="inspectstats" class="hint" style="margin-top:20px">Load a survey to inspect its coverage.</div><h3 style="font-size:12px;margin-top:22px">Connected dead zones</h3><div id="inspectclusters"></div><button id="openanalysis" class="full">Open full analysis ↗</button>`;workspace.append(inspector);
const details=document.createElement('button');details.textContent='Survey details';details.id='inspecttoggle';document.querySelector('.titlebar').append(details);
function toggleInspector(open=!workspace.classList.contains('inspector-open')){workspace.classList.toggle('inspector-open',open);inspector.classList.toggle('hidden',!open);details.setAttribute('aria-expanded',String(open));}details.onclick=()=>toggleInspector();inspector.querySelector('button').onclick=()=>toggleInspector(false);toggleInspector(innerWidth>1400);
const nav=[...document.querySelectorAll('nav button')];nav[1].textContent='Analysis';nav[2].textContent='2D comparison';nav[1].removeAttribute('data-stage');nav[2].removeAttribute('data-stage');nav[1].onclick=()=>emit('app-view','analysis');nav[2].onclick=()=>emit('app-view','comparison');$('openanalysis').onclick=nav[1].onclick;
let snapshot=null,charts=[],chartDirty=true,txEdited=false;
document.addEventListener('app-view',e=>{const view=e.detail;workspace.classList.toggle('hidden',view!=='map');document.querySelector('.hardware').classList.toggle('hidden',view!=='hardware');analysis.classList.toggle('hidden',view!=='analysis');comparison.classList.toggle('hidden',view!=='comparison');nav.forEach((n,i)=>n.classList.toggle('selected',i===({map:0,analysis:1,comparison:2,hardware:3}[view])));if(view==='analysis'){if(chartDirty)drawCharts();requestAnimationFrame(()=>charts.forEach(c=>c.resize()));}if(view==='comparison')requestAnimationFrame(drawComparison);});
const fmt=(n,dp=1)=>n===null||n===undefined||!Number.isFinite(n)?'—':n.toFixed(dp);
const xyz=p=>p?[p.x,p.y,p.z].map(n=>fmt(n)).join(' / '):'—';
function card(label,value,note){return `<div class="reportcard"><label>${label}</label><b>${value}</b><small>${note}</small></div>`;}
export function analysisConfig(){return {frequencyMHz:+$('frequency').value,txPowerDbm:+$('txpower').value};}
export function updateAnalysis(next){snapshot=next;const s=next.summary;$('analysisname').textContent=next.name;$('analysisdead').value=next.thresholds.dead;
  if(!txEdited){const powers=next.samples.filter(r=>r.received!==false&&Number.isFinite(r.tx_dbm)).map(r=>r.tx_dbm);if(powers.length){const same=powers.every(p=>p===powers[0]);$('txpower').value=powers.at(-1);$('txassumption').textContent=same?'TX baseline read from payload records.':'TX power varies; baseline uses the last received TX value.';}else $('txassumption').textContent='TX baseline is assumed; edit to match your beacon.';}
  next.radio=analysisConfig();
  const warning=[];if(s.simulated)warning.push('Positions in this survey are simulated.');if(!s.volumetric)warning.push('This survey is planar or spatially degenerate; measured 3D volume cannot be established.');if(s.bleMissingReports)warning.push(`${s.bleMissingReports} BLE reports were missing within this capture; packet-ID gaps are not solely RF loss.`);$('analysiswarning').textContent=warning.join(' ');$('analysiswarning').classList.toggle('hidden',!warning.length);
  $('analysiscards').innerHTML=card('Total reports',s.sampleCount.toLocaleString(),`${s.receivedCount} received · ${s.timeoutCount} timeout events`)+card('RSSI mean / min / max',`${fmt(s.meanRSSI)} dBm`,`${fmt(s.minRSSI)} min · ${fmt(s.maxRSSI)} max`)+card('Mean SNR',`${fmt(s.meanSNR)} dB`,'Received packets only; timeout sentinels excluded')+card('Inferred packet loss',`${fmt(s.packetLoss.percent,2)}%`,`${s.packetLoss.lost} counter gaps · ${s.packetLoss.resets} resets`)+card('Dead-zone volume',s.deadVolumeM3===null?'Unavailable':`${fmt(s.deadVolumeM3)} m³`,`${fmt(s.deadPercent)}% of supported cells · ${s.deadVoxelCount} cells`)+card('Supported volume',s.supportedVolumeM3===null?'Planar survey':`${fmt(s.supportedVolumeM3)} m³`,'Estimated occupied grid cells, not a measured room volume')+card('Worst measured location',xyz(s.worst),`${fmt(s.worst?.RSSI_dBm)} dBm · X / Y / Z meters`)+card('Connected regions',String(s.clusters.length),`Threshold < ${next.thresholds.dead} dBm · ${next.resolution} m cells`);
  $('inspectstats').innerHTML=`<div class="inspectmetric"><span>Mean SNR</span><b>${fmt(s.meanSNR)} dB</b><small>${s.receivedCount} received measurements</small></div><div class="inspectmetric"><span>Dead-zone estimate</span><b>${s.deadVolumeM3===null?'Planar survey':fmt(s.deadVolumeM3)+' m³'}</b><small>${fmt(s.deadPercent)}% of supported cells</small></div><div class="inspectmetric"><span>Worst measured X / Y / Z</span><b style="font-size:13px">${xyz(s.worst)}</b><small>${fmt(s.worst?.RSSI_dBm)} dBm</small></div><div class="inspectmetric"><span>Capture quality</span><b>${s.timeoutCount} timeouts</b><small>${s.bleMissingReports} BLE reports missing${s.simulated?' · simulated coordinates':''}</small></div>`;
  $('clusterrows').innerHTML=s.clusters.length?s.clusters.slice(0,200).map(c=>`<tr><td>DZ-${String(c.id).padStart(2,'0')}</td><td>${xyz(c.centroid)}</td><td>${c.count}</td><td>${s.volumetric?fmt(c.count*next.resolution**3)+' m³':'Not volumetric'}</td><td>${fmt(c.minRSSI)} dBm</td><td><button data-focus="${c.id}">Focus ↗</button></td></tr>`).join(''):'<tr><td colspan="6" class="reportempty">No connected voxels below this threshold. Adjust the dead-zone threshold or load a survey.</td></tr>';
  $('clustersummary').textContent=s.clusters.length>200?`Showing the largest 200 of ${s.clusters.length} regions; JSON includes every region.`:'';
  $('inspectclusters').innerHTML=s.clusters.slice(0,5).map(c=>`<button class="clusterlink" data-focus="${c.id}">DZ-${String(c.id).padStart(2,'0')} · ${c.count} cells · ${fmt(c.minRSSI)} dBm ↗</button>`).join('')||'<p class="hint">No regions below the dead-zone threshold.</p>';
  for(const root of [$('clusterrows'),$('inspectclusters')])root.querySelectorAll('[data-focus]').forEach(b=>b.onclick=()=>{const c=s.clusters.find(c=>c.id===+b.dataset.focus);emit('app-view','map');emit('focus-location',{...c.centroid,extent:Math.max(4,Math.cbrt(c.count)*next.resolution)});});
  const levels=altitudeLevels(next.voxels),previous=+$('compalt').value;$('compalt').replaceChildren(...levels.map(z=>{const o=document.createElement('option');o.value=z;o.textContent=z.toFixed(2)+' m';return o;}));if(levels.includes(previous))$('compalt').value=previous;else if(levels.length)$('compalt').value=levels[Math.floor(levels.length/2)];chartDirty=true;if(!analysis.classList.contains('hidden'))drawCharts();if(!comparison.classList.contains('hidden'))drawComparison();
}
function drawCharts(){if(!snapshot||typeof Chart==='undefined')return;charts.forEach(c=>c.destroy());charts=[];const data=chartSample(snapshot.samples),good=data.filter(s=>s.received!==false),start=snapshot.samples[0].Timestamp_ms,beaconZ=snapshot.beacon.altitudeM,radio=analysisConfig(),distance=p=>Math.hypot(p.x,p.y,p.z-beaconZ);const config=(canvas,datasets,xTitle)=>new Chart($(canvas),{type:'scatter',data:{datasets},options:{animation:false,parsing:false,responsive:true,maintainAspectRatio:false,plugins:{legend:{labels:{color:'#a2b4c6',boxWidth:12,font:{size:10}}},tooltip:{callbacks:{label:c=>`${c.dataset.label}: ${c.parsed.y.toFixed(1)} dBm`}}},scales:{x:{type:'linear',title:{display:true,text:xTitle,color:'#92a7bb'},grid:{color:'#223245'},ticks:{color:'#7c91a7',maxTicksLimit:8}},y:{title:{display:true,text:'RSSI · dBm',color:'#92a7bb'},grid:{color:'#223245'},ticks:{color:'#7c91a7'}}}}});
  const dataset=(points,label='Measured RSSI',color='#b6ed6b')=>({label,data:points,backgroundColor:color,borderColor:color,pointRadius:2,pointHoverRadius:5});
  charts.push(config('timechart',[dataset(good.map(p=>({x:(p.Timestamp_ms-start)/1000,y:p.RSSI_dBm})))],'Elapsed time · seconds'));
  charts.push(config('altchart',[dataset(good.map(p=>({x:p.z,y:p.RSSI_dBm})),'Measured RSSI','#65c9c6')],'Logged altitude · m'));
  const maxD=Math.max(1,...good.map(distance)),theory=Array.from({length:100},(_,i)=>{const d=1+(maxD-1)*i/99;return {x:d,y:freeSpaceRSSI(d,radio.txPowerDbm,radio.frequencyMHz)};});charts.push(config('distancechart',[dataset(good.map(p=>({x:distance(p),y:p.RSSI_dBm})))],'Beacon distance · m'));
  const chart=charts.at(-1);chart.data.datasets.push({...dataset(theory,'Ideal free-space baseline','#e1a561'),showLine:true,pointRadius:0,borderWidth:1.5,borderDash:[5,5]});chart.update('none');chartDirty=false;
}
function heatmap(canvas,points,label){const ctx=canvas.getContext('2d'),rect=canvas.getBoundingClientRect(),dpr=Math.min(devicePixelRatio,2);canvas.width=Math.max(300,Math.round(rect.width*dpr));canvas.height=Math.max(240,Math.round(rect.height*dpr));ctx.scale(dpr,dpr);const w=canvas.width/dpr,h=canvas.height/dpr;ctx.fillStyle='#0b1420';ctx.fillRect(0,0,w,h);if(!snapshot)return;const all=snapshot.samples;if(!all.length)return;const minX=Math.min(...all.map(v=>v.x)),minY=Math.min(...all.map(v=>v.y)),maxX=Math.max(...all.map(v=>v.x)),maxY=Math.max(...all.map(v=>v.y)),res=snapshot.resolution,nx=Math.round((maxX-minX)/res)+1,ny=Math.round((maxY-minY)/res)+1,size=Math.min((w-75)/nx,(h-65)/ny),left=(w-nx*size)/2,top=20;
  if(nx*ny>20000){ctx.fillStyle='#a7b8c8';ctx.fillText('Survey footprint is too large for this slice view.',20,40);return;}
  const cells=new Map();for(const p of points){const ix=Math.round((p.x-minX)/res),iy=Math.round((p.y-minY)/res),key=`${ix},${iy}`,c=cells.get(key)||{sum:0,count:0};c.sum+=p.RSSI_dBm;c.count++;cells.set(key,c);}
  for(let x=0;x<nx;x++)for(let y=0;y<ny;y++){const px=left+x*size,py=top+(ny-1-y)*size,c=cells.get(`${x},${y}`);ctx.fillStyle=c?'rgb('+signalRGB(c.sum/c.count,snapshot.thresholds).join(',')+')':'#152231';ctx.fillRect(px,py,Math.max(.5,size-1),Math.max(.5,size-1));if(!c&&size>5){ctx.strokeStyle='#2a3d50';ctx.beginPath();ctx.moveTo(px,py+size-1);ctx.lineTo(px+size-1,py);ctx.stroke();}}
  ctx.fillStyle='#8ca3b8';ctx.font='10px monospace';ctx.textAlign='center';ctx.fillText(`X east: ${minX.toFixed(1)} → ${maxX.toFixed(1)} m`,w/2,h-15);ctx.save();ctx.translate(15,h/2);ctx.rotate(-Math.PI/2);ctx.fillText(`Y north: ${minY.toFixed(1)} → ${maxY.toFixed(1)} m`,0,0);ctx.restore();if(!cells.size){ctx.fillStyle='#dce5ed';ctx.font='12px sans-serif';ctx.fillText('No observations at this height',w/2,h/2);}$(label).textContent=`${cells.size} observed/estimated cells · ${nx*ny-cells.size} unknown · common XY footprint`;}
function drawComparison(){if(!snapshot)return;const z=+$('compalt').value,ground=+$('groundheight').value,flight=sliceAt(snapshot.voxels,z,1e-4),measured=sliceAt(snapshot.samples.filter(p=>p.received!==false),ground,snapshot.resolution/2);heatmap($('flightslice'),flight,'flightcoverage');heatmap($('groundslice'),measured,'groundcoverage');$('comparisondetail').textContent=`Flight slice: ${Number.isFinite(z)?z.toFixed(2):'—'} m. Ground observations: ${ground.toFixed(2)} ± ${(snapshot.resolution/2).toFixed(2)} m. ${measured.length?'Ground view uses only measured rows in this band.':'There are no measured received packets in this ground band; coverage is unknown.'} ${!snapshot.summary.volumetric?'This survey does not span a 3D volume.':''} Hatched cells indicate missing data.`;}
$('compalt').onchange=drawComparison;$('groundheight').oninput=drawComparison;new ResizeObserver(()=>{if(!comparison.classList.contains('hidden'))drawComparison();}).observe(comparison);
$('analysisdead').onchange=()=>{const v=+$('analysisdead').value;if(v>=+$('fading').value){$('analysisdead').value=$('dead').value;return;}$('dead').value=v;emit('recompute-survey');};
for(const id of ['txpower','frequency'])$(id).onchange=()=>{if(!$('frequency').value||+$('frequency').value<=0){$('frequency').value=433;}txEdited=true;if(snapshot)snapshot.radio=analysisConfig();chartDirty=true;drawCharts();emit('radio-config',analysisConfig());};
function download(name,text,type){const a=document.createElement('a'),url=URL.createObjectURL(new Blob([text],{type}));a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);$('exportstatus').textContent='Exported '+name;}
$('gridexport').onclick=()=>{if(!snapshot)return $('exportstatus').textContent='Load a survey first.';download('rf-interpolated-grid.csv',gridCSV(snapshot),'text/csv');};$('jsonexport').onclick=()=>{if(!snapshot)return $('exportstatus').textContent='Load a survey first.';download('rf-survey-summary.json',JSON.stringify(report(snapshot),null,2),'application/json');};$('pngexport').onclick=()=>emit('export-map-png');
document.addEventListener('map-png-exported',()=>{$('exportstatus').textContent='Exported rf-spatial-map.png';});
